import Link from "next/link";
import Dropzone from "@/components/Dropzone";
import Scorecard from "@/components/Scorecard";
import sampleGrade from "@/lib/sample-grade.json";
import type { Grade } from "@/lib/types";

/**
 * Landing page.
 *
 * One decision per screen: the dropzone IS the primary CTA and sits above the
 * fold. Everything else — how it works, the example score, the depth on
 * /how-it-works — is below it or one click away, and never blocks the path from
 * landing to score.
 */

// Generated by scripts/export_sample_grade.py from the committed sample fleet.
const SAMPLE = sampleGrade.grade as unknown as Grade;
const SAMPLE_FLEET = sampleGrade.fleet;

function StepIcon({ d }: { d: string }) {
  return (
    <svg
      className="step-icon"
      aria-hidden="true"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d={d} />
    </svg>
  );
}

const STEPS = [
  {
    // upload arrow
    icon: "M12 16V4m0 0L8 8m4-4 4 4M4 16v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2",
    title: "Upload your plan",
    body: "A CSV of routes and stops. Non-standard column names are fine — we map them for you.",
  },
  {
    // scales / benchmark
    icon: "M12 3v18M5 8l-3 6h6l-3-6Zm14 0-3 6h6l-3-6ZM5 8l7-2 7 2",
    title: "We score and re-solve it",
    body: "Five dimensions of quality, plus an independent re-solve of your own stops to see what was achievable.",
  },
  {
    // map
    icon: "M9 4 3 7v13l6-3 6 3 6-3V4l-6 3-6-3Zm0 0v13m6-10v13",
    title: "See score, findings, and map",
    body: "A letter grade, the specific inefficiencies behind it, and every route on an interactive map.",
  },
];

export default function Home() {
  return (
    <>
      <section className="hero">
        <div className="container hero-inner">
          <h1>Benchmark your last-mile routes.</h1>
          <p className="lede">
            Upload a route plan, get an independent quality score in minutes.
          </p>

          {/* The CTA is the dropzone itself — no intermediate "get started". */}
          <Dropzone />

          <p className="hero-aside">
            No account needed.{" "}
            <Link href="/how-it-works">How it works, in detail →</Link>
          </p>
        </div>
      </section>

      <section className="container">
        <h2 className="section-title">How it works</h2>
        <ol className="steps">
          {STEPS.map((step, i) => (
            <li key={step.title} className="step">
              <StepIcon d={step.icon} />
              <h3>
                <span className="step-n">{i + 1}</span> {step.title}
              </h3>
              <p>{step.body}</p>
            </li>
          ))}
        </ol>
      </section>

      <section className="container">
        <h2 className="section-title">What you get</h2>
        <p className="section-lede">
          A letter grade you can act on, decomposed into the five dimensions
          behind it. Every number traces back to a specific finding — nothing is
          a black box.
        </p>

        <Scorecard
          grade={SAMPLE}
          caption={`Example — ${SAMPLE_FLEET.routes} routes, ${SAMPLE_FLEET.stops} stops`}
        />

        <p className="disclosure">
          This is a real grade of our published{" "}
          <Link href="/how-it-works#sample">sample fleet</Link>, computed with the
          same rubric your upload gets (v{SAMPLE.grading_version}). It is
          illustrative, not a benchmark to beat — the sample fleet was built to
          contain a problem in every category.
        </p>
      </section>
    </>
  );
}
